def lfu_cache(maxsize=128, typed=False):
    from collections import OrderedDict, defaultdict

    class LfuCache:
        def __init__(self, maxsize):
            self.maxsize = maxsize
            self.cache = OrderedDict()
            self.freq_count = defaultdict(int)
            self.freq_cache = defaultdict(OrderedDict)

        def get(self, key):
            if key not in self.cache:
                return None
            self.freq_count[key] += 1
            if self.freq_count[key] > 1:
                self.freq_cache[self.freq_count[key].pop(key)].move_to_end(key)
            self.cache.move_to_end(key)
            return self.cache[key]

        def put(self, key, value):
            if key in self.cache:
                self.cache[key] = value
                self.freq_count[key] += 1
                if self.freq_count[key] > 1:
                    self.freq_cache[self.freq_count[key].pop(key)].move_to_end(key)
            else:
                if len(self.cache) == self.maxsize:
                    least_freq_key = self.freq_cache[min(self.freq_cache)]
                    least_freq_key.popitem(last=False)
                    del self.freq_count[least_freq_key[0][0]]
                self.cache[key] = value
                self.freq_count[key] = 1
                self.freq_cache[1][key] = value

        def key_set(self):
            return self.cache.keys()

