def formatmany(self, sql: str | bytes, many_params: Iterable[dict[str | int, Any]] | Iterable[Sequence[Any]]) -> tuple[str | bytes, list[dict[str | int, Any]] | list[Sequence[Any]]]:
    formatted_sql = sql
    converted_params = []

    for params in many_params:
        converted_list = []

        for key, value in params.items():
            if self.SQLParams.in_style == 'named':
                formatted_sql = formatted_sql.replace(f'\\{key}', f'{key}')
                converted_list.append({'name': key, 'value': value})
            elif self.SQLParams.in_style == 'ordinal':
                if isinstance(value, dict):
                    # Assuming ordinal parameter style with a key-value dictionary
                    for key, value in value.items():
                        formatted_sql = formatted_sql.replace(f'\\{key}', f'{key}')
                        converted_list.append({'value': value})
                elif isinstance(value, list):
                    # Assuming ordinal parameter style with a list of values
                    for i, value in enumerate(value):
                        formatted_sql = formatted_sql.replace(f'\\{i}', f'{i}')
                        converted_list.append({'value': value})
                else:
                    # Assuming ordinal parameter style with a simple single value
                    formatted_sql = formatted_sql.replace(f'\\{0}', f'{0}')
                    converted_list.append({'value': value})

        converted_params.append(converted_list)

    return formatted_sql, converted_params
