def pretty(self, indent=0, debug=False):
    pretty = ""
    if debug:
        pretty += f"DEBUG: Indent at: {indent}\n"
    pretty += f"{type(self).__name__}: "
    if hasattr(self, '__iter__'):
        if isinstance(self, (list, tuple, set)):
            pretty += f"["
            if debug:
                pretty += f"DEBUG: Starting list\n"
            for item in self:
                pretty += f"{indent}{item.pretty(indent+2, debug)}\n"
                if debug:
                    pretty += f"DEBUG: Finished list\n"
            pretty += f"{indent}]"
        elif isinstance(self, dict):
            pretty += "{"
            if debug:
                pretty += f"DEBUG: Starting dict\n"
            for key, value in sorted(self.items(), key=lambda item: item[0]):
                pretty += f"{indent}{key}: {value.pretty(indent+2, debug)}\n"
                if debug:
                    pretty += f"DEBUG: Finished dict\n"
            pretty += f"{indent}}"
        else:
            pretty += str(self)
    else:
        pretty += str(self)
    if debug:
        pretty += f"DEBUG: Finishing pretty formatting\n"
    return pretty
