def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number == 0:
        return "0"

    visited = set()
    result = []

    while number > 0:
        digit = number % len(alphabet)
        if digit in visited:
            raise ValueError("Duplicate occurrence of digit")
        result.insert(0, alphabet[digit])
        visited.add(digit)
        number //= len(alphabet)

    if padding is not None and len(result) < padding:
        result.extend(["0"] * (padding - len(result)))

    return ''.join(result)
