def _verify(iface, candidate, tentative=False, vtype=None):
    # Making sure the candidate claims that it provides the interface
    if tentative:
        return True  # Tentative verification is skipped

    # Checking if the candidate claims to implement the interface
    if not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not provide {iface}")

    # Checking if the candidate defines all necessary methods and attributes
    errors = []
    for method_name in iface.implementedMethods():
        call_method = getattr(candidate, method_name)
        if hasattr(iface, method_name) and getattr(iface, method_name).im_func == call_method.im_func:
            continue  # Same method in the candidate file cannot be overridden by <conforming> file
        if not callable(call_method):
            errors.append(f"{candidate}.{method_name} is not callable")
        elif call_method.__code__ != getattr(iface, method_name).__code__:
            errors.append(f"{candidate}.{method_name} has the wrong signature")

    for attr_name in iface.implementedAttributes():
        attr_value = getattr(candidate, attr_name)
        if hasattr(iface, attr_name) and getattr(iface, attr_name).im_func == attr_value.im_func:
            continue  # Same attribute in the candidate file cannot be overridden by <conforming> file
        if not hasattr(attr_value, '__get__') or not callable(attr_value.__get__):
            errors.append(f"{candidate}.{attr_name} is not an attribute")

    if errors:
        if len(errors) == 1:
            raise errors[0]  # Special case: if only one error is present, raise alone
        raise zope.interface.Invalid(errors)
    else:
        return True
